'use strict';
const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localeOptions={'en-US':'USD','en-GB':'GBP','fr-FR':'EUR'};
let activeLocale=localStorage.getItem('foodnow-locale')||'en-US';if(!localeOptions[activeLocale])activeLocale='en-US';
const money=(n,currency=localeOptions[activeLocale])=>new Intl.NumberFormat(activeLocale,{style:'currency',currency:currency.toUpperCase()}).format((n||0)/100);
const date=s=>new Date(s).toLocaleString(activeLocale,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
let config={mode:'rehearsal',restaurants:[],catalog:[]}, session={user:{},csrf:''}, portal='diner',cart=[],category='All',search='',version=0,poll,toastTimer,work=null,orderFilter='all';
try{cart=JSON.parse(sessionStorage.getItem('foodnow-cart')||'[]');if(!Array.isArray(cart))cart=[]}catch{}
const roles={diner:'Diner',restaurant:'Restaurant owner',courier:'Delivery courier',operations:'FoodNow operations'};
const homes={diner:'discover',restaurant:'owner/overview',courier:'courier/deliveries',operations:'ops/overview'};
const stages={payment_pending:'Awaiting payment',placed:'New order',accepted:'Accepted',preparing:'Preparing',ready:'Ready for pickup',picked_up:'On the way',delivered:'Delivered'};
const paymentLabels={succeeded:'Paid',requires_payment_method:'Payment needed',processing:'Processing',canceled:'Canceled',not_started:'Not started'};
function routeParts(){return (location.hash.slice(1)||'discover').split('?')[0].split('/')}
function currentPortal(){const [p,sub]=routeParts();return p==='owner'?'restaurant':p==='courier'?'courier':p==='ops'?'operations':['login','register'].includes(p)?sub||'diner':'diner'}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-FoodNow-Locale':activeLocale,'X-FoodNow-Portal':portal,'X-CSRF-Token':session.csrf||''},...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await r.json()}catch{throw Error('The server could not complete the request. Try again.')}if(!r.ok){const e=Error(data.error||'Request failed');e.status=r.status;throw e}return data}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function notice(s,type=''){return `<div class="notice ${type}">${s}</div>`}
function badge(s){return `<span class="pill ${['approved','succeeded','delivered'].includes(s)?'green':['pending','payment_pending','requires_payment_method'].includes(s)?'amber':''}">${escapeHtml(stages[s]||paymentLabels[s]||s)}</span>`}
function saveCart(){sessionStorage.setItem('foodnow-cart',JSON.stringify(cart));sessionStorage.removeItem('foodnow-market-attempt');header()}
function dish(id){return config.catalog.find(d=>d.id===id)}
function subtotal(){return cart.reduce((n,i)=>n+(dish(i.dishId)?.amount||0)*i.quantity,0)}
function header(){const user=session.user,workspace=portal!=='diner'&&!['login','register','portals'].includes(routeParts()[0]);$('#mode-label').textContent=config.mode==='rehearsal'?'Rehearsal · Payments simulated':'Stripe test mode · No real charges';$('#mode-label').textContent+=' · '+activeLocale+' / '+localeOptions[activeLocale];$('#site-header').innerHTML=`<a class="brand" href="#discover"><span class="brand-symbol">f<span>n</span></span>foodnow<span class="brand-dot">.</span></a>${workspace?`<span class="workspace-label">${roles[portal]}</span>`:`<button class="location" id="address-button"><span class="pin">⌖</span><span><small>Deliver to</small><strong>${escapeHtml(sessionStorage.getItem('foodnow-address')||'River North, Chicago')}</strong></span><span>⌄</span></button>`}<label class="locale-control">Checkout locale<select id="locale-picker">${Object.entries(localeOptions).map(([l,c])=>`<option value="${l}" ${l===activeLocale?'selected':''}>${l} · ${c}</option>`).join('')}</select></label><nav aria-label="Main navigation">${workspace?'<a href="#discover">Diner storefront ↗</a><a href="#portals">Workspaces</a>':'<a href="#discover">Discover</a><a href="#orders">My orders</a><a href="#roadmap">FoodNow+</a><a href="#portals">Workspaces</a>'}</nav>${!workspace?`<a class="bag" href="#bag">Bag <span>${cart.reduce((n,i)=>n+i.quantity,0)}</span></a>`:''}${user.id?`<button class="account-button" id="account-button"><span class="avatar">${escapeHtml(user.name.slice(0,1))}</span><span>${escapeHtml(user.name.split(' ')[0])}</span></button>`:`<a class="button outline login-link" href="#login/${portal}">Sign in</a>`}`;
 $('#locale-picker').onchange=e=>{activeLocale=e.target.value;localStorage.setItem('foodnow-locale',activeLocale);sessionStorage.removeItem('foodnow-market-attempt');route()};
 if($('#address-button'))$('#address-button').onclick=addressDialog;if($('#account-button'))$('#account-button').onclick=()=>{modal(`<h2>${escapeHtml(user.name)}</h2><p>${escapeHtml(user.email)}</p><p class="meta">${roles[user.role]}</p><button class="button spacer" id="signout">Sign out of this workspace</button>`);$('#signout').onclick=async()=>{await api('/api/auth/logout',{});$('#modal').close();location.hash='login/'+portal;route()}};
}
function addressDialog(){modal(`<h2>Delivery address</h2><p class="meta">Locale changes payment currency and formatting. This demo retains its sample Chicago restaurants.</p><form id="address-form" class="spacer"><label class="field">Address<input name="address" required maxlength="200" value="${escapeHtml(sessionStorage.getItem('foodnow-address')||'123 W Hubbard St, Chicago, IL')}"></label><button class="button full">Save address</button></form>`);$('#address-form').onsubmit=e=>{e.preventDefault();sessionStorage.setItem('foodnow-address',new FormData(e.target).get('address').trim());$('#modal').close();header()}}
function totals(){return `<div class="totals"><div class="row"><span>Food subtotal</span><span>${money(subtotal())}</span></div><div class="row"><span>Delivery</span><span>${money(399)}</span></div><div class="row"><span>Service fee</span><span>${money(199)}</span></div><div class="row total"><span>Total</span><span>${money(subtotal()+598)}</span></div></div><p class="note">Sample prices use the selected currency, not an exchange rate. Taxes and tips excluded.</p>`}
function bagMarkup(checkout=false){return `<h3>Your bag <span class="pill">${cart.reduce((n,i)=>n+i.quantity,0)} items</span></h3>${cart.length?`${cart.map(i=>`<div class="cart-line"><div class="row"><strong>${escapeHtml(dish(i.dishId)?.title||'Unavailable item')}</strong><span>${money((dish(i.dishId)?.amount||0)*i.quantity)}</span></div>${!checkout?`<div class="quantity spacer"><button data-qty="${i.dishId}" data-delta="-1" aria-label="Remove one ${escapeHtml(dish(i.dishId)?.title)}">−</button><span>${i.quantity}</span><button data-qty="${i.dishId}" data-delta="1" aria-label="Add one ${escapeHtml(dish(i.dishId)?.title)}">+</button></div>`:`<p class="note">Quantity ${i.quantity}</p>`}</div>`).join('')}${totals()}${!checkout?'<a class="button full spacer" href="#checkout">Checkout →</a>':''}`:'<div class="empty">Your next great meal starts here.<br>Add a dish to your bag.</div>'}`}
function add(id){const d=dish(id);if(!d){toast('This dish is no longer available. Refresh the menu.');return}if(cart.length&&dish(cart[0].dishId)?.restaurantId!==d.restaurantId){modal('<h2>Start a new restaurant order?</h2><p>Each order comes from one restaurant. Your current bag will be replaced.</p><button class="button spacer" id="replace-bag">Start new bag</button>');$('#replace-bag').onclick=()=>{cart=[];$('#modal').close();add(id)};return}let i=cart.find(x=>x.dishId===id);if(i){if(i.quantity>=10){toast('Maximum 10 per dish');return}i.quantity++}else cart.push({dishId:id,quantity:1});saveCart();if($('#cart-panel'))$('#cart-panel').innerHTML=bagMarkup();toast('Added to your bag')}
function restaurantCard(r){return `<button class="restaurant-card" data-restaurant="${r.id}"><div class="card-image"><img src="${r.image}" alt="Representative ${escapeHtml(r.cuisine)} food"><span class="card-tag">${escapeHtml(r.cuisine)}</span></div><div class="card-copy"><div class="row"><h3>${escapeHtml(r.name)}</h3><span class="rating">★ ${r.rating}</span></div><p class="meta">${escapeHtml(r.description)}</p><div class="card-footer"><span>◷ ${r.deliveryTime}</span><span>${money(399)} delivery</span></div></div></button>`}
function filterRestaurants(){const filtered=config.restaurants.filter(r=>(category==='All'||category===r.cuisine)&&`${r.name} ${r.cuisine}`.toLowerCase().includes(search.toLowerCase()));$('#restaurant-results').innerHTML=filtered.length?filtered.map(restaurantCard).join(''):'<div class="empty">No matches. Try another cuisine or restaurant name.</div>'}
function discover(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Your neighborhood. Delivered.</span><h1>Good food.<br><em>Right now.</em></h1><p>Five cuisines. Local kitchens. Your next favorite.</p><label class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search restaurants" type="search" placeholder="Search restaurants or cuisines" value="${escapeHtml(search)}"></label></div><div class="hero-image"><img src="/images/pizza.jpg" alt="Freshly baked pizza"><div class="image-caption"><div><strong>Basil & Brick</strong><small>Fresh from the wood-fired oven</small></div><span class="rating">★ 4.9</span></div></div></section><div class="category-row" aria-label="Cuisine filters">${['All','Pizza','Burgers','Healthy','Indian','Japanese'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}" aria-pressed="${c===category}">${c==='All'?'All restaurants':c}</button>`).join('')}</div><div class="section-heading"><div><h2>Your next great meal</h2><p>Order as a guest, or sign in to keep your order history.</p></div><span class="meta">${config.restaurants.length} restaurants</span></div><div class="restaurant-grid" id="restaurant-results"></div><section class="plus-banner"><span class="plus-icon">✦</span><div><h3>A little more to look forward to. FoodNow+</h3><p>Explore the NEXT chapter of the marketplace.</p></div><a class="button" href="#membership">Membership preview →</a></section>`}
function restaurantPage(id){const r=config.restaurants.find(x=>x.id===id);if(!r)return '<div class="empty">Restaurant not currently available.</div>';const items=config.catalog.filter(i=>i.restaurantId===id);return `<a class="back" href="#discover">← All restaurants</a><div class="restaurant-header"><div><span class="pill">${escapeHtml(r.cuisine)}</span><h1>${escapeHtml(r.name)}</h1><p class="meta">${escapeHtml(r.description)}</p><p class="spacer"><span class="rating">★ ${r.rating}</span> &nbsp; ${r.deliveryTime} · ${money(399)} delivery</p><p class="note">${escapeHtml(r.address)}</p></div><img src="${r.image}" alt="${escapeHtml(r.cuisine)} food"></div><div class="two-col"><section><h2>On the menu</h2><div class="menu-list">${items.length?items.map(i=>`<article class="dish"><div><h3>${escapeHtml(i.title)}</h3><p>${escapeHtml(i.description)}</p><div class="row"><strong>${money(i.amount)}</strong><button class="button" data-add="${i.id}">Add +</button></div></div><img src="${i.image}" alt="Representative dish photo"></article>`).join(''):'<div class="empty">The owner is preparing the menu. Check back shortly.</div>'}</div><p class="note">Photos are representative. Contact the restaurant about allergens.</p></section><aside class="panel sticky" id="cart-panel">${bagMarkup()}</aside></div>`}
function portals(){return `<div class="page-top"><span class="eyebrow">The FoodNow marketplace</span><h1>Your work. Your workspace.</h1><p>Separate logins connect the people behind every order. Open different workspaces in separate tabs to follow the same order together.</p></div><div class="portal-grid">${[['diner','Find your next favorite','Browse five cuisines, pay securely and follow your delivery.','Order food'],['restaurant','Run your restaurant','Register your business, manage your menu and keep orders moving.','Restaurant workspace'],['courier','Keep the city moving','Get onboarded, pick up orders and track your delivery earnings.','Courier workspace'],['operations','See the whole marketplace','Review partners, coordinate orders and reconcile money movement.','Operations workspace']].map(([role,title,desc,cta],index)=>`<article class="portal-card ${role==='operations'?'dark':''}"><span class="portal-number">0${index+1}</span><span class="eyebrow">${roles[role]}</span><h2>${title}</h2><p>${desc}</p><a class="button ${role==='operations'?'':'secondary'}" href="#${role==='diner'?'discover':homes[role]}">${cta} →</a>${role!=='diner'?`<a class="text-button" href="#login/${role}" target="_blank" rel="noopener">Open login in a separate tab ↗</a>`:'<a class="text-button" href="#login/diner">Diner sign in →</a>'}</article>`).join('')}</div>`}
function loginPage(role,register=false){const valid=roles[role]?role:'diner';return `<div class="auth-layout"><div class="auth-story"><a class="back" href="#portals">← All workspaces</a><span class="eyebrow">${roles[valid]}</span><h1>${register?'Your next chapter<br>starts here.':valid==='operations'?'The whole marketplace.<br>One clear view.':valid==='restaurant'?'Made in your kitchen.<br>Managed your way.':valid==='courier'?'Your deliveries.<br>Your momentum.':'Welcome back.<br>What sounds good?'}</h1><p>${register?'Create your account. Restaurant and courier registrations are reviewed by FoodNow operations.':'Sign in to see the orders, people and payment records that belong to your account.'}</p><div class="auth-steps"><span>1. Sign in</span><span>2. Open your workspace</span><span>3. Keep orders moving</span></div></div><section class="panel auth-panel"><h2>${register?'Create an account':'Sign in'}</h2><p class="meta">${roles[valid]}</p><form id="auth-form" class="spacer">${register?'<label class="field">Your name<input name="name" required maxlength="80" autocomplete="name"></label>':''}<label class="field">Email<input name="email" type="email" required maxlength="254" autocomplete="username"></label><label class="field">Password<input name="password" type="password" required minlength="10" maxlength="160" autocomplete="${register?'new-password':'current-password'}"></label>${register&&valid==='restaurant'?'<label class="field">Restaurant name<input name="businessName" required maxlength="80"></label><label class="field">Cuisine<select name="cuisine"><option>Pizza</option><option>Burgers</option><option>Healthy</option><option>Indian</option><option>Japanese</option></select></label><label class="field">Business address<input name="address" required maxlength="200" placeholder="Chicago, IL"></label>':''}${register&&valid==='courier'?'<label class="field">How will you deliver?<select name="vehicle"><option>Bicycle</option><option>Car</option><option>Scooter</option><option>Walking</option></select></label>':''}<div id="auth-error" role="alert"></div><button class="button full">${register?'Create account':'Sign in'} →</button></form>${valid!=='operations'?`<p class="note spacer">${register?'Already registered?':'New to FoodNow?'} <a class="text-button" href="#${register?'login':'register'}/${valid}">${register?'Sign in':'Create an account'}</a></p>`:''}${valid==='diner'?'<a class="button secondary full spacer" href="#discover">Continue as a guest</a>':''}${!register?`<details class="demo-credentials spacer"><summary>Use a sample ${roles[valid].toLowerCase()} account</summary><p class="note">Local demo accounts use <strong>FoodNowDemo!2026</strong>.</p>${(valid==='operations'?['ops']:valid==='courier'?['courier','jamie']:valid==='restaurant'?['basil','bun','green','spice','maki']:['diner']).map(x=>`<button type="button" class="sample-account" data-demo-email="${x}@foodnow.demo">${x}@foodnow.demo <span>Fill form →</span></button>`).join('')}</details>`:''}</section></div>`}
function authBindings(role,register){document.querySelectorAll('[data-demo-email]').forEach(b=>b.onclick=()=>{const f=$('#auth-form');f.elements.email.value=b.dataset.demoEmail;f.elements.password.value='FoodNowDemo!2026'});$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button[type=submit],button:not([type])');b.disabled=true;$('#auth-error').innerHTML='';try{const data=Object.fromEntries(new FormData(form));const result=await api('/api/auth/'+(register?'register':'login'),{...data,role});session={...session,...result};location.hash=homes[role];}catch(err){$('#auth-error').innerHTML=`<div class="error">${escapeHtml(err.message)}</div>`;b.disabled=false}}}
function checkoutPage(){if(!cart.length)return '<div class="page-top"><h1>Your bag is empty.</h1></div><a class="button" href="#discover">Find a restaurant</a>';return `<a href="#bag" class="back">← Back to your bag</a><div class="page-top"><span class="eyebrow">${session.user.id?'Diner checkout':'Guest checkout'}</span><h1>Almost at your door.</h1><p>${session.user.id?'Your order will appear in your account history.':'No account needed. This browser session will let you track your order.'}</p></div><div class="two-col"><section class="panel"><h3>Delivery details</h3><form id="checkout-form"><div class="form-grid"><label class="field">Name<input name="name" required maxlength="80" value="${escapeHtml(session.user.name||'')}" autocomplete="name"></label><label class="field">Email<input name="email" required type="email" maxlength="254" value="${escapeHtml(session.user.email||'')}" autocomplete="email"></label><label class="field wide">Delivery address<input name="address" required maxlength="200" value="${escapeHtml(sessionStorage.getItem('foodnow-address')||'123 W Hubbard St, Chicago, IL')}" autocomplete="street-address"></label></div>${config.mode==='rehearsal'?`${notice('<strong>Payment rehearsal</strong><br>These payment choices simulate the checkout experience. No card or wallet is charged.')}<div class="payment-methods" role="group" aria-label="Simulated payment method">${['Card','Apple Pay','Google Pay','Link'].map((m,i)=>`<label class="method-option"><input type="radio" name="method" value="${m}" ${i===0?'checked':''}><span>${m}</span></label>`).join('')}</div><div class="payment-preview" aria-label="Non-interactive card form preview"><span class="eyebrow">Card layout preview · not a Stripe Element</span><div class="preview-field">Card number <strong>4242 4242 4242 4242</strong></div><div class="form-grid"><div class="preview-field">Expiry <strong>12 / 34</strong></div><div class="preview-field">CVC <strong>•••</strong></div></div><p class="note">Configure Stripe test mode to replace this preview with Stripe’s hosted secure fields and eligible wallet buttons.</p></div><label class="field spacer">Test outcome<select name="outcome"><option value="succeeded">Payment succeeds</option><option value="requires_payment_method">Payment declined · try another method</option><option value="processing">Payment processing</option></select></label>`:notice('<strong>Secure payment with Stripe</strong><br>Continue below to load the real Payment Element and eligible express checkout buttons. Test details only.')}<div id="express-checkout-element"></div><div id="payment-element"></div><div id="checkout-error" role="alert"></div><button class="button full spacer" id="pay-button">${config.mode==='rehearsal'?'Place demo order · '+money(subtotal()+598):'Continue to payment'}</button></form><p class="note">Fictional restaurant demo. No food is dispatched.</p></section><aside class="panel">${bagMarkup(true)}</aside></div>`}
async function checkoutBindings(){if(!$('#checkout-form'))return;let stripe,elements,orderId;$('#checkout-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=$('#pay-button');button.disabled=true;$('#checkout-error').innerHTML='';try{const fields=Object.fromEntries(new FormData(form));const signature=JSON.stringify({locale:activeLocale,cart,email:fields.email.toLowerCase().trim(),name:fields.name.trim(),address:fields.address.trim()});let attempt;try{attempt=JSON.parse(sessionStorage.getItem('foodnow-market-attempt'))}catch{}if(!attempt||attempt.signature!==signature){attempt={token:crypto.randomUUID(),signature};sessionStorage.setItem('foodnow-market-attempt',JSON.stringify(attempt))}if(!orderId){const result=await api('/api/checkout',{checkoutToken:attempt.token,items:cart,email:fields.email,name:fields.name,address:fields.address});orderId=result.orderId;attempt.orderId=orderId;sessionStorage.setItem('foodnow-market-attempt',JSON.stringify(attempt));sessionStorage.setItem('foodnow-last-order',orderId);sessionStorage.setItem('foodnow-address',fields.address);for(const key of ['email','name','address'])form.elements[key].readOnly=true;if(result.status==='succeeded'){location.hash='order/'+orderId;return}if(config.mode==='stripe'){if(!window.Stripe)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://js.stripe.com/v3/';s.onload=resolve;s.onerror=()=>reject(Error('Stripe could not load. Check your connection and retry.'));document.head.append(s)});stripe=Stripe(config.publishableKey);elements=stripe.elements({clientSecret:result.clientSecret,locale:activeLocale==='fr-FR'?'fr':'en',appearance:{theme:'stripe',variables:{colorPrimary:'#635bff',colorText:'#0a2540',borderRadius:'10px'}}});const express=elements.create('expressCheckout');express.on('confirm',async()=>{try{const {error:submitError}=await elements.submit();if(submitError)throw submitError;const r=await stripe.confirmPayment({elements,confirmParams:{return_url:location.origin+'/#order/'+orderId},redirect:'if_required'});if(r.error)throw r.error;location.hash='order/'+orderId}catch(err){$('#checkout-error').textContent=err.message}});express.mount('#express-checkout-element');const payment=elements.create('payment',{layout:'tabs',defaultValues:{billingDetails:{name:fields.name,email:fields.email}}});payment.on('loaderror',()=>{$('#checkout-error').innerHTML='<div class="error">Payment form could not load. Refresh and retry.</div>'});payment.mount('#payment-element');button.textContent=(activeLocale==='fr-FR'?'Payer ':'Pay ')+money(result.amount);button.disabled=false;return}}
if(config.mode==='rehearsal'){const result=await api('/api/orders/'+orderId+'/simulate',{outcome:fields.outcome,method:fields.method});if(result.status==='requires_payment_method')throw Error('Payment declined. Try another payment method or select a successful outcome. Your order has been preserved.');location.hash='order/'+orderId;return}
const result=await stripe.confirmPayment({elements,confirmParams:{return_url:location.origin+'/#order/'+orderId},redirect:'if_required'});if(result.error)throw Error(result.error.message);location.hash='order/'+orderId;
}catch(err){if(config.mode==='stripe'&&!elements)orderId=null;$('#checkout-error').innerHTML=`<div class="error">${escapeHtml(err.message)}</div>`;button.disabled=false}}}
function trackingPage(o){const sequence=['placed','accepted','preparing','ready','picked_up','delivered'],position=sequence.indexOf(o.stage);return `<a class="back" href="#orders">← My orders</a><div class="two-col"><section class="panel"><span class="eyebrow">${escapeHtml(o.restaurantName)} · ${config.mode==='rehearsal'?'Simulated payment':'Stripe test payment'}</span><h1 style="font-size:2.5rem">${o.stage==='delivered'?'Enjoy every bite.':o.stage==='picked_up'?'Your food is on its way.':o.stage==='payment_pending'?'Confirming your payment.':'Your order is in.'}</h1><p class="meta spacer">${o.stage==='payment_pending'?'The kitchen receives your order after payment confirmation.':'The restaurant and courier update this timeline as your order moves.'}</p><div class="tracking-steps">${sequence.map((s,i)=>`<div class="tracking-step ${i<=position?'done':''}"><span>${i<position?'✓':i+1}</span><strong>${stages[s]}</strong></div>`).join('')}</div><p class="note">Updates automatically every five seconds.</p><div class="actions"><button class="button secondary" id="refresh-tracking">Refresh status</button>${o.status!=='succeeded'&&config.mode==='rehearsal'?'<button class="button" id="confirm-demo-payment">Simulate payment confirmation</button>':''}</div><h3 class="spacer">Order updates</h3><div class="activity-feed">${[...o.history].reverse().map(h=>`<div><span>${date(h.at)}</span><p>${escapeHtml(h.note)}</p></div>`).join('')}</div></section><aside class="panel"><h3>Delivery details</h3><p>${escapeHtml(o.buyerName)}</p><p class="meta">${escapeHtml(o.address)}</p><h3 class="spacer">Your order</h3>${o.items.map(i=>`<div class="cart-line row"><span>${i.quantity} × ${escapeHtml(i.title)}</span><strong>${money(i.lineTotal,o.currency)}</strong></div>`).join('')}<div class="totals"><div class="row"><span>Delivery + service</span><span>${money(598,o.currency)}</span></div><div class="row total"><span>Total</span><span>${money(o.amount,o.currency)}</span></div></div>${badge(o.status)}<p class="note">${escapeHtml(o.paymentMethod||'Payment not completed')}</p><p class="note mono">${o.id}</p></aside></div>`}
function dinerOrders(orders){return `<div class="page-top"><span class="eyebrow">${session.user.id?'Your account':'Guest orders in this browser session'}</span><h1>Your cravings, on record.</h1><p>Follow an active delivery or look back at a favorite meal.</p></div>${orders.length?`<div class="order-grid">${[...orders].reverse().map(o=>`<a class="panel order-history-card" href="#order/${o.id}"><div class="row"><h3>${escapeHtml(o.restaurantName)}</h3>${badge(o.stage)}</div><p class="meta">${o.items.map(i=>i.quantity+' × '+escapeHtml(i.title)).join(', ')}</p><div class="row spacer"><strong>${money(o.amount,o.currency)}</strong><span class="meta">${date(o.createdAt)}</span></div><span class="text-button">Track order →</span></a>`).join('')}</div>`:'<div class="panel empty"><h3>No orders yet</h3><p>Your next favorite is waiting.</p><a class="button spacer" href="#discover">Explore restaurants</a></div>'}`}
function metric(label,value,detail){return `<article class="metric"><small>${label}</small><strong>${value}</strong><p>${detail}</p></article>`}
function shell(role,section,content){const prefix=role==='operations'?'ops':role==='restaurant'?'owner':'courier';const links=role==='operations'?[['overview','Overview'],['restaurants','Restaurants'],['couriers','Couriers'],['orders','Open orders'],['payments','Transactions'],['stripe','Stripe insights']]:role==='restaurant'?[['overview','Overview'],['orders','Order queue'],['menu','My menu'],['payments','Payments'],['onboarding','Onboarding']]:[['deliveries','My deliveries'],['earnings','My earnings'],['onboarding','Onboarding']];return `<div class="workspace-shell"><aside class="workspace-sidebar"><div class="sidebar-identity"><span class="avatar">${escapeHtml(session.user.name.slice(0,1))}</span><strong>${escapeHtml(role==='restaurant'?work.restaurants[0]?.name||session.user.name:session.user.name)}</strong><small>${roles[role]}</small></div><nav aria-label="Workspace navigation">${links.map(([id,label],i)=>`<a class="${section===id?'selected':''}" href="#${prefix}/${id}"><span class="nav-icon">${['◫','▤','▦','⇄','◎','✦'][i]}</span>${label}</a>`).join('')}</nav><div class="sidebar-note"><span class="pill">${config.mode==='rehearsal'?'REHEARSAL':'STRIPE TEST'}</span><p>${config.mode==='rehearsal'?'Orders and partner actions are persistent. Payment outcomes are simulated.':'Real test-account objects. No live payments.'}</p></div></aside><div class="workspace-content">${content}</div></div>`}
function workspaceTop(kicker,title,description,action=''){return `<div class="page-top"><span class="eyebrow">${kicker}</span><div class="row"><h1>${title}</h1>${action||'<button class="button outline" data-refresh>Refresh</button>'}</div><p>${description}</p></div>`}
function orderActions(o,role){if(o.status!=='succeeded')return badge(o.status);if(role==='restaurant'){const next={placed:'accepted',accepted:'preparing',preparing:'ready'}[o.stage];return next?`<button class="button" data-state="${next}" data-id="${o.id}">${{accepted:'Accept order',preparing:'Start preparing',ready:'Ready for pickup'}[next]}</button>`:badge(o.stage)}if(role==='courier'){const next={ready:'picked_up',picked_up:'delivered'}[o.stage];return next?`<button class="button" data-state="${next}" data-id="${o.id}">${next==='picked_up'?'Confirm pickup':'Confirm delivery'}</button>`:badge(o.stage)}return `<button class="text-button" data-inspect="${o.id}">View order →</button>`}
function queueCards(orders,role){return orders.length?`<div class="queue-grid">${orders.map(o=>`<article class="panel queue-card"><div class="row"><span class="mono">${o.id.slice(0,12)}</span>${badge(o.stage)}</div><h3>${role==='restaurant'?escapeHtml(o.buyerName):escapeHtml(o.restaurantName)}</h3><p class="meta">${o.items.map(i=>i.quantity+' × '+escapeHtml(i.title)).join('<br>')}</p>${role==='courier'?`<div class="delivery-address"><small>Pick up from ${escapeHtml(o.restaurantName)}</small><p>${escapeHtml(o.pickupAddress)}</p><small>Deliver to</small><p>${escapeHtml(o.address)}</p><p class="note">${escapeHtml(o.buyerName)}</p></div>`:''}<div class="row spacer"><span class="meta">${date(o.createdAt)}</span><strong>${money(role==='courier'?o.earnings:o.subtotal,o.currency)}</strong></div><div class="actions">${orderActions(o,role)}<button class="text-button" data-inspect="${o.id}">Details</button></div></article>`).join('')}</div>`:'<div class="panel empty"><h3>All caught up.</h3><p>New orders appear here as they become ready for your next action.</p></div>'}
function orderTable(orders,role='operations'){return `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Restaurant / customer</th><th>Status</th><th>${role==='operations'?'Customer paid':'Your earnings'}</th><th>Settlement</th><th></th></tr></thead><tbody>${[...orders].reverse().map(o=>`<tr><td class="mono">${o.id.slice(0,12)}<small class="table-sub">${date(o.createdAt)}</small></td><td>${escapeHtml(o.restaurantName)}<small class="table-sub">${escapeHtml(o.buyerName)}</small></td><td>${badge(o.stage)}</td><td>${money(role==='operations'?o.amount:o.earnings,o.currency)}</td><td>${role==='operations'?Object.keys(o.transfers||{}).length===2?'Transferred':Object.keys(o.transfers||{}).length?'Partial':'Pending':o.transferId?'Transferred':'Pending'}</td><td><button data-inspect="${o.id}">Inspect →</button></td></tr>`).join('')||'<tr><td colspan="6">No orders in this view yet.</td></tr>'}</tbody></table></div>`}
function ledgerTable(entries){return `<div class="table-wrap"><table><thead><tr><th>Journal / order</th><th>Account</th><th>Partner</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${[...entries].reverse().map(e=>`<tr><td>${escapeHtml(e.description)}<small class="table-sub mono">${e.orderId.slice(0,12)}</small></td><td>${escapeHtml(e.account.replaceAll('_',' '))}</td><td>${escapeHtml(work?.restaurants.find(r=>r.id===e.partnerId)?.name||work?.couriers.find(c=>c.id===e.partnerId)?.name||e.partnerId)}</td><td>${e.debit?money(e.debit):'—'}</td><td>${e.credit?money(e.credit):'—'}</td></tr>`).join('')||'<tr><td colspan="5">Entries appear when payments are confirmed.</td></tr>'}</tbody></table></div>`}
function partnerTable(kind){const list=kind==='restaurant'?work.restaurants:work.couriers;return `<div class="table-wrap"><table><thead><tr><th>${kind==='restaurant'?'Restaurant':'Courier'}</th><th>Application</th><th>Onboarding</th><th>${kind==='restaurant'?'Commission':'Vehicle'}</th><th>Orders</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${escapeHtml(p.name)}</strong><small class="table-sub">${escapeHtml(kind==='restaurant'?p.cuisine:p.vehicle)}</small></td><td>${badge(p.approval)}</td><td>${p.onboardingComplete?'Details submitted':'Not completed'}<small class="table-sub">${p.transfersReady?'Transfers ready':'Transfers not ready'}${config.mode==='rehearsal'?' · simulated':''}</small></td><td>${kind==='restaurant'?p.commissionBps/100+'%':escapeHtml(p.vehicle)}</td><td>${work.orders.filter(o=>kind==='restaurant'?o.restaurantId===p.id:o.courierId===p.id).length}</td><td>${p.approval==='pending'?`<div class="actions"><button data-review="approved" data-kind="${kind}" data-id="${p.id}">Approve</button><button data-review="rejected" data-kind="${kind}" data-id="${p.id}">Decline</button></div>`:`<button data-partner="${kind}" data-id="${p.id}">Details →</button>`}</td></tr>`).join('')}</tbody></table></div>`}
function operationsPage(section){const paid=work.orders.filter(o=>o.status==='succeeded'),open=paid.filter(o=>o.stage!=='delivered'),pendingR=work.restaurants.filter(r=>r.approval==='pending'),pendingC=work.couriers.filter(c=>c.approval==='pending');const filtered=orderFilter==='all'?work.orders:work.orders.filter(o=>o.restaurantId===orderFilter);let content;
if(section==='stripe'){content=stripeInsights()}
else if(section==='overview'){content=workspaceTop('Marketplace operations','A clear view of every handoff.','Review new partners, keep open orders moving and follow the money.')+`<div class="metric-grid four">${metric('Open orders',open.length,'Paid orders still in progress')}${metric('Partner applications',pendingR.length+pendingC.length,`${pendingR.length} restaurants · ${pendingC.length} couriers`)}${metric('Customer payments',money(paid.reduce((n,o)=>n+o.amount,0)),config.mode==='rehearsal'?'Simulated confirmed volume':'Confirmed Stripe test volume')}${metric('Platform revenue',money(paid.reduce((n,o)=>n+o.platformEarnings,0)),'Commission + service fees, before costs')}</div><div class="section-heading"><h2>Open orders by restaurant</h2><a class="text-button" href="#ops/orders">All orders →</a></div><div class="restaurant-summary-grid">${work.restaurants.filter(r=>r.approval==='approved').map(r=>{const list=open.filter(o=>o.restaurantId===r.id);return `<article class="panel"><div class="row"><h3>${escapeHtml(r.name)}</h3><span class="pill">${list.length} open</span></div><p class="meta">${escapeHtml(r.cuisine)}</p><div class="mini-stages">${['placed','preparing','ready','picked_up'].map(s=>`<span>${stages[s]} <b>${list.filter(o=>o.stage===s).length}</b></span>`).join('')}</div><a class="text-button" href="#ops/orders" data-filter-restaurant="${r.id}">View orders →</a></article>`}).join('')}</div><section class="panel spacer"><div class="row"><h3>Registration requests</h3><span class="pill amber">${pendingR.length+pendingC.length} pending</span></div><p class="meta">Restaurant and courier sign-ups enter the review queue. FoodNow approval and Stripe verification are separate checks.</p><div class="actions"><a class="button secondary" href="#ops/restaurants">Review restaurants</a><a class="button secondary" href="#ops/couriers">Review couriers</a></div></section>`}
else if(section==='restaurants'||section==='couriers'){const kind=section==='restaurants'?'restaurant':'courier';content=workspaceTop('Partner network',section==='restaurants'?'Restaurants, ready to grow.':'Couriers, ready to move.','Review applications and distinguish business approval from payment readiness.')+partnerTable(kind)}
else if(section==='orders'){content=workspaceTop('Order control','From kitchen to doorstep.','Assign an approved courier and inspect every order across the marketplace.')+restaurantFilter()+orderTable(filtered)}
else{const entries=orderFilter==='all'?work.ledger:work.ledger.filter(e=>e.restaurantId===orderFilter);const debit=entries.reduce((n,e)=>n+e.debit,0),credit=entries.reduce((n,e)=>n+e.credit,0);content=workspaceTop('Payment operations','Every debit. Every credit.','Balanced commercial journals trace customer payments, liabilities and transfers.')+restaurantFilter()+`<div class="metric-grid">${metric('Debits',money(debit),'Entries in the selected restaurant scope')}${metric('Credits',money(credit),'Same scope and currency')}${metric('Journal balance',money(debit-credit),'Debits minus credits; expected zero')}</div><div class="section-heading"><h2>Order settlement</h2><span class="pill">${config.mode==='rehearsal'?'SIMULATED':'STRIPE TEST'}</span></div>`+orderTable(filtered)+`<h2 class="spacer">Journal entries</h2><p class="note">Sale: debit clearing, credit partner payables and platform revenue. Transfer: debit payable, credit clearing. Bank payouts are separate.</p>`+ledgerTable(entries)}return shell('operations',section,content)}
function restaurantFilter(){return `<label class="filter-label">Restaurant<select class="control" id="restaurant-filter"><option value="all">All restaurants</option>${work.restaurants.map(r=>`<option value="${r.id}" ${orderFilter===r.id?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label>`}
function onboardingPage(role){const p=role==='restaurant'?work.restaurants[0]:work.couriers[0];return workspaceTop('Partner onboarding','A few steps to get moving.','Your FoodNow application and Stripe payment readiness have separate statuses.')+`<div class="partner-grid"><section class="panel"><span class="eyebrow">01 · FoodNow review</span><h2>${escapeHtml(p.name)}</h2><p class="spacer">Application status: ${badge(p.approval)}</p><p class="meta spacer">${p.approval==='pending'?'Operations will review your application. You can prepare your profile while you wait.':p.approval==='approved'?'You are approved to work on FoodNow.':'Your application was declined. Contact FoodNow operations.'}</p>${p.reviewNote?notice(escapeHtml(p.reviewNote)):''}</section><section class="panel"><span class="eyebrow">02 · Payment setup</span><h2>Get ready to receive earnings.</h2><ul class="checklist"><li>Business or personal details: ${p.onboardingComplete?'submitted':'needed'}</li><li>Transfers: ${p.transfersReady?'ready':'not ready'}</li><li>Bank payouts: ${p.payoutsEnabled?'enabled':'not enabled'}</li></ul>${config.mode==='rehearsal'?notice('Rehearsal onboarding changes local demo readiness only. No identity information or bank details are collected.'):notice('Stripe collects required identity and bank information in its hosted flow. Returning here does not guarantee approval.')}<div class="actions"><button class="button" id="start-onboarding">${config.mode==='rehearsal'?'Complete rehearsal onboarding':'Continue with Stripe'} →</button><button class="button secondary" id="refresh-onboarding">Check readiness</button></div>${p.requirements?.length?`<p class="note">Outstanding: ${p.requirements.map(escapeHtml).join(', ')}</p>`:''}${p.stripeAccount?`<p class="note mono">${p.stripeAccount}</p>`:''}</section></div>`}
function ownerPage(section){const r=work.restaurants[0],orders=work.orders,paid=orders.filter(o=>o.status==='succeeded'),open=paid.filter(o=>o.stage!=='delivered');let content;
if(section==='onboarding')content=onboardingPage('restaurant');
else if(section==='menu'){content=workspaceTop('Menu management','Your menu, made by you.','Add dishes, change prices and mark items unavailable. Existing orders keep their original prices.','<button class="button" id="add-menu-item">Add a dish +</button>')+`<div class="menu-management">${work.menu.map(i=>`<article class="panel menu-management-card"><img src="${i.image}" alt="Representative dish photo"><div><div class="row"><h3>${escapeHtml(i.title)}</h3><span class="pill ${i.available?'green':'amber'}">${i.available?'Available':'Unavailable'}</span></div><p class="meta">${escapeHtml(i.description)}</p><div class="row spacer"><strong>${money(i.amount)}</strong><button class="button secondary" data-edit-menu="${i.id}">Edit dish</button></div></div></article>`).join('')||'<div class="panel empty">Add your first dish to start building your menu.</div>'}</div>`}
else if(section==='payments'){content=workspaceTop('Restaurant finances','Your orders. Your earnings.','Track customer payments, FoodNow commission and transfers to your connected balance.')+`<div class="metric-grid">${metric('Food sales',money(paid.reduce((n,o)=>n+o.subtotal,0)),'Confirmed paid food subtotal')}${metric('Your earnings',money(paid.reduce((n,o)=>n+o.earnings,0)),`${r.commissionBps/100}% FoodNow commission deducted`)}${metric('Transferred',money(paid.filter(o=>o.transferId).reduce((n,o)=>n+o.earnings,0)),'To connected balance, before bank payouts')}</div>`+orderTable(orders,'restaurant')+`<h2 class="spacer">Your payable account</h2><p class="note">Credits add earnings owed to you; debits settle those earnings.</p>`+ledgerTable(work.ledger)}
else if(section==='orders'){content=workspaceTop('Kitchen queue','A good service starts here.','Accept paid orders, start preparing, then mark them ready for the courier.')+queueCards(open,'restaurant')+`<h2 class="spacer">Completed orders</h2>`+orderTable(orders.filter(o=>o.stage==='delivered'),'restaurant')}
else{content=workspaceTop(escapeHtml(r.name),'Your kitchen, at a glance.','Keep the queue moving and make your next menu update.')+(r.approval!=='approved'?notice(`Application ${escapeHtml(r.approval)}. Visit Onboarding for your review status.`,'warn'):'')+`<div class="metric-grid">${metric('New orders',open.filter(o=>o.stage==='placed').length,'Ready for you to accept')}${metric('In the kitchen',open.filter(o=>['accepted','preparing'].includes(o.stage)).length,'Accepted and preparing')}${metric('Restaurant earnings',money(paid.reduce((n,o)=>n+o.earnings,0)),'Before your operating costs')}</div><div class="section-heading"><h2>Needs your attention</h2><a href="#owner/orders" class="text-button">Full queue →</a></div>`+queueCards(open.slice(0,4),'restaurant')+`<section class="panel spacer"><h3>Make the menu yours.</h3><p class="meta">You have ${work.menu.filter(i=>i.available).length} available dishes. Changes appear in the diner storefront.</p><a class="button secondary spacer" href="#owner/menu">Manage menu →</a></section>`}return shell('restaurant',section,content)}
function courierPage(section){const c=work.couriers[0],delivered=work.orders.filter(o=>o.stage==='delivered'),active=work.orders.filter(o=>o.stage!=='delivered');let content;
if(section==='onboarding')content=onboardingPage('courier');
else if(section==='earnings'){content=workspaceTop('Courier earnings','Every delivery adds up.','Track completed delivery earnings and transfers to your connected balance.')+`<div class="metric-grid">${metric('Completed deliveries',delivered.length,'Confirmed by you')}${metric('Earned',money(delivered.reduce((n,o)=>n+o.earnings,0)),money(399)+' per delivery in this demo')}${metric('Transferred',money(delivered.filter(o=>o.transferId).reduce((n,o)=>n+o.earnings,0)),'Bank payouts are separate')}</div>`+orderTable(work.orders,'courier')+`<h2 class="spacer">Your payable account</h2><p class="note">Assigned earnings remain pending until delivery. Credits establish the payable; debits record transfers.</p>`+ledgerTable(work.ledger)}
else{content=workspaceTop('Delivery workspace',`Let’s get moving, ${escapeHtml(c.name.split(' ')[0])}.`,'See your assignments, confirm pickup and complete each delivery.')+(c.approval!=='approved'?notice('Your application is awaiting review. Complete onboarding while operations reviews it.','warn'):'')+`<div class="metric-grid">${metric('Active deliveries',active.length,'Your assigned orders')}${metric('Completed',delivered.length,'Delivered to the customer')}${metric('Earned today in this demo',money(delivered.filter(o=>new Date(o.history.find(h=>h.state==='delivered')?.at||o.createdAt).toDateString()===new Date().toDateString()).reduce((n,o)=>n+o.earnings,0)),'Completed delivery fees')}</div><h2 class="section-heading">Your deliveries</h2>`+queueCards(active,'courier')+`<h2 class="spacer">Available pickups</h2><p class="meta">Ready orders without a courier. Claiming an order reserves it for you.</p><div class="queue-grid spacer">${(work.availableOrders||[]).map(o=>`<article class="panel"><h3>${escapeHtml(o.restaurantName)}</h3><p class="meta">${escapeHtml(o.pickupAddress)}</p><div class="row spacer"><strong>${money(o.earnings,o.currency)} delivery earnings</strong><button class="button" data-claim="${o.id}">Claim delivery</button></div></article>`).join('')||'<div class="panel empty">No unassigned pickups right now.</div>'}</div>`}return shell('courier',section,content)}
async function inspectOrder(id){const o=await api('/api/orders/'+id);const ops=portal==='operations';modal(`<div class="row"><h2>${escapeHtml(o.restaurantName)}</h2></div><div class="row">${badge(o.stage)}${badge(o.status)}</div><p class="note mono">${o.id}</p>${o.items.map(i=>`<div class="cart-line row"><span>${i.quantity} × ${escapeHtml(i.title)}</span><strong>${money(i.lineTotal,o.currency)}</strong></div>`).join('')}${ops?`<div class="money-flow"><div><small>Restaurant net</small><strong>${money(o.restaurantEarnings,o.currency)}</strong></div><div><small>Courier delivery fee</small><strong>${money(o.courierEarnings,o.currency)}</strong></div><div><small>FoodNow retained</small><strong>${money(o.platformEarnings,o.currency)}</strong></div></div><p class="note">Customer total ${money(o.amount,o.currency)}. FoodNow retained amount is before processing and operating costs.</p><p class="note">Processing fee: ${o.feeReconciled?money(o.processingFee,o.currency):'Not reconciled; no estimated fee is presented as actual.'}</p>`:`<div class="notice"><strong>Your earnings: ${money(o.earnings,o.currency)}</strong><br>${o.transferId?'Transferred to your connected balance.':'Transfer pending; settlement follows delivery.'}</div>`}${o.address?`<div class="delivery-address"><small>Delivery address</small><p>${escapeHtml(o.address)}</p></div>`:''}<div class="activity-feed spacer">${o.history.map(h=>`<div><span>${date(h.at)}</span><p>${escapeHtml(h.note)}</p></div>`).join('')}</div><div id="inspect-error" role="alert"></div>${ops?`<div class="spacer">${!o.courierId&&o.status==='succeeded'&&o.stage!=='delivered'?`<label class="field">Assign a courier<select id="assign-courier"><option value="">Choose an approved courier</option>${work.couriers.filter(c=>c.approval==='approved').map(c=>`<option value="${c.id}">${escapeHtml(c.name)} · ${escapeHtml(c.vehicle)}</option>`).join('')}</select></label><button class="button secondary" id="assign-button">Assign courier</button>`:`<p class="note">Courier: ${escapeHtml(work.couriers.find(c=>c.id===o.courierId)?.name||'Not assigned')}</p>`}<div class="actions"><button class="button" id="settle-button" ${o.stage!=='delivered'?'disabled':''}>${Object.keys(o.transfers||{}).length===2?'Recheck settlement':config.mode==='rehearsal'?'Settle simulated earnings':'Transfer test earnings'}</button>${config.mode==='stripe'&&o.status==='succeeded'?'<button class="button secondary" id="fee-button">Reconcile Stripe fee</button>':''}${config.mode==='stripe'&&o.paymentIntentId?`<a class="text-button" target="_blank" rel="noopener" href="https://dashboard.stripe.com/test/payments/${encodeURIComponent(o.paymentIntentId)}">View payment in Stripe ↗</a>`:''}</div><p class="note">${Object.entries(o.transfers||{}).map(([r,id])=>escapeHtml(r)+': '+escapeHtml(id)).join('<br>')||'No transfers yet. Delivered orders are eligible for settlement.'}</p></div>`:''}`);
 const act=async(path,body={})=>{try{await api(path,body);$('#modal').close();await route(true);await inspectOrder(id)}catch(e){$('#inspect-error').innerHTML=`<div class="error">${escapeHtml(e.message)}</div>`}};
 if($('#assign-button'))$('#assign-button').onclick=()=>act('/api/orders/'+id+'/assign',{courierId:$('#assign-courier').value});if($('#settle-button'))$('#settle-button').onclick=async()=>{$('#settle-button').disabled=true;await act('/api/orders/'+id+'/allocate');if($('#settle-button'))$('#settle-button').disabled=o.stage!=='delivered'};if($('#fee-button'))$('#fee-button').onclick=()=>act('/api/orders/'+id+'/reconcile-fee');}
function menuDialog(id){const item=work.menu.find(i=>i.id===id);modal(`<h2>${item?'Edit your dish':'Add a new dish'}</h2><form id="menu-form"><label class="field">Dish name<input name="title" required maxlength="100" value="${escapeHtml(item?.title||'')}"></label><label class="field">Description<textarea name="description" maxlength="400" rows="3">${escapeHtml(item?.description||'')}</textarea></label><label class="field">Price (USD)<input type="number" name="price" min="1" max="1000" step="0.01" required value="${item?item.amount/100:''}"></label><label class="check-field"><input type="checkbox" name="available" ${!item||item.available?'checked':''}> Available to order</label><p class="note">The restaurant’s representative photo is used for this dish. Existing orders retain their original prices.</p><div id="menu-error" role="alert"></div><button class="button full spacer">Save dish</button></form>`);$('#menu-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await api('/api/menu',{id:item?.id||'',title:f.get('title'),description:f.get('description'),amount:Math.round(Number(f.get('price'))*100),available:f.has('available')});$('#modal').close();await route(true);toast('Menu updated. Diners will see your changes.')}catch(e){$('#menu-error').innerHTML=`<div class="error">${escapeHtml(e.message)}</div>`;b.disabled=false}}}
function reviewDialog(kind,id,decision){const p=(kind==='restaurant'?work.restaurants:work.couriers).find(x=>x.id===id);modal(`<h2>${decision==='approved'?'Approve':'Decline'} ${escapeHtml(p.name)}?</h2><p>FoodNow business approval is separate from Stripe payment readiness.</p><form id="review-form" class="spacer"><label class="field">Note to the partner<textarea name="note" rows="3" maxlength="300" placeholder="Optional review note"></textarea></label><div id="review-error" role="alert"></div><button class="button">${decision==='approved'?'Approve application':'Decline application'}</button></form>`);$('#review-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/partners/${kind}/${id}/review`,{decision,note:new FormData(e.target).get('note')});$('#modal').close();await route(true);toast('Application reviewed')}catch(e){$('#review-error').innerHTML=`<div class="error">${escapeHtml(e.message)}</div>`}}}
function partnerDetails(kind,id){const p=(kind==='restaurant'?work.restaurants:work.couriers).find(x=>x.id===id);const orders=work.orders.filter(o=>kind==='restaurant'?o.restaurantId===id:o.courierId===id),paid=orders.filter(o=>o.status==='succeeded');modal(`<h2>${escapeHtml(p.name)}</h2>${badge(p.approval)}<p class="meta spacer">${escapeHtml(p.cuisine||p.vehicle)}</p>${p.address?`<p class="meta">${escapeHtml(p.address)}</p>`:''}<div class="metric-grid"><div class="metric"><small>Orders</small><strong>${orders.length}</strong></div><div class="metric"><small>Earnings</small><strong>${money(paid.reduce((n,o)=>n+(kind==='restaurant'?o.restaurantEarnings:o.courierEarnings),0))}</strong></div></div><ul class="checklist"><li>Onboarding: ${p.onboardingComplete?'details submitted':'not completed'}</li><li>Transfers: ${p.transfersReady?'ready':'not ready'}</li><li>Bank payouts: ${p.payoutsEnabled?'enabled':'not enabled'}</li></ul>${kind==='restaurant'?`<p class="meta">FoodNow commission: ${p.commissionBps/100}% of food subtotal.</p>`:'<p class="meta">Delivery earnings: '+money(399)+' per completed delivery in this demo.</p>'}<p class="note">${escapeHtml(p.reviewNote||'No review note')}</p><p class="note mono">${escapeHtml(p.stripeAccount||'Stripe account not created')}</p>`)}
async function setStatus(id,next){if(next==='delivered'){modal('<h2>Confirm this delivery</h2><p>Confirm you handed the order to the customer or left it at their requested delivery location.</p><button class="button full spacer" id="confirm-delivery">Yes, the order is delivered</button><div id="delivery-error" role="alert"></div>');$('#confirm-delivery').onclick=async()=>{try{await api('/api/orders/'+id+'/status',{next,confirmed:true});$('#modal').close();await route(true);toast('Delivery confirmed. Your earnings are recorded.')}catch(e){$('#delivery-error').innerHTML=`<div class="error">${escapeHtml(e.message)}</div>`}}}else{await api('/api/orders/'+id+'/status',{next,confirmed:false});await route(true);toast('Order status updated')}}
function workspaceBindings(){document.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=()=>route(true));if($('#restaurant-filter'))$('#restaurant-filter').onchange=e=>{orderFilter=e.target.value;route(true)};if($('#verify-stripe-account'))$('#verify-stripe-account').onclick=verifyStripeAccount;if($('#refresh-stripe-evidence'))$('#refresh-stripe-evidence').onclick=refreshStripeEvidence;if($('#add-menu-item'))$('#add-menu-item').onclick=()=>menuDialog();if($('#start-onboarding'))$('#start-onboarding').onclick=async()=>{const b=$('#start-onboarding');b.disabled=true;try{const r=await api('/api/connect/start',{});if(r.url){location.assign(r.url);return}toast(r.message);route(true)}catch(e){toast(e.message);b.disabled=false}};if($('#refresh-onboarding'))$('#refresh-onboarding').onclick=async()=>{try{await api('/api/connect/refresh',{});route(true)}catch(e){toast(e.message)}}}
async function route(quiet=false){clearInterval(poll);const v=++version;portal=currentPortal();const [raw,sub]=routeParts();let page=raw;if(page==='operations'){location.hash='ops/overview';return}if(page==='partners'){location.hash='portals';return}if(!quiet){$('#modal').close();window.scrollTo(0,0);$('#app').innerHTML='<div class="loading">Getting everything ready…</div>'}try{const [identity,catalog]=await Promise.all([api('/api/session'),api('/api/config')]);if(v!==version)return;session=identity;config=catalog;document.documentElement.lang=activeLocale;header();document.title='FoodNow · '+(roles[portal]||'Discover');document.body.classList.toggle('workspace-mode',['owner','ops','courier'].includes(page));const app=$('#app');
 if(page==='discover'){app.innerHTML=discover();filterRestaurants();$('#search').oninput=e=>{search=e.target.value;filterRestaurants()}}
 else if(page==='restaurant')app.innerHTML=restaurantPage(sub);
 else if(page==='bag'){const missing=cart.filter(i=>!dish(i.dishId));app.innerHTML=`<div class="page-top"><h1>Your bag</h1></div>${missing.length?notice('An item is no longer available. Remove it before checkout.','warn'):''}<div class="panel" style="max-width:650px" id="cart-panel">${bagMarkup()}</div>`}
 else if(page==='portals')app.innerHTML=portals();
 else if(page==='login'||page==='register'){const role=roles[sub]?sub:'diner';if(page==='register'&&role==='operations'){location.hash='login/operations';return}app.innerHTML=loginPage(role,page==='register');authBindings(role,page==='register')}
 else if(page==='checkout'){app.innerHTML=checkoutPage();checkoutBindings()}
 else if(page==='orders'){const list=await api('/api/orders');if(v!==version)return;app.innerHTML=dinerOrders(list)}
 else if(page==='order'){const o=await api('/api/orders/'+encodeURIComponent(sub));if(v!==version)return;app.innerHTML=trackingPage(o);$('#refresh-tracking').onclick=()=>route(true);if($('#confirm-demo-payment'))$('#confirm-demo-payment').onclick=async()=>{await api('/api/orders/'+sub+'/simulate',{outcome:'succeeded',method:'Card'});route(true)};let a;try{a=JSON.parse(sessionStorage.getItem('foodnow-market-attempt'))}catch{}if(o.status==='succeeded'&&a?.orderId===o.id){cart=[];saveCart()}}
 else if(['owner','ops','courier'].includes(page)){if(!session.user.id){app.innerHTML=loginPage(portal);authBindings(portal,false)}else{work=await api('/api/workspace');if(portal==='operations')work.insights=await api('/api/insights');if(v!==version)return;const section=sub|| (portal==='courier'?'deliveries':'overview');app.innerHTML=portal==='operations'?operationsPage(section):portal==='restaurant'?ownerPage(section):courierPage(section);workspaceBindings()}}
 else if(page==='roadmap'){app.innerHTML=roadmapPage();$('#later-details').onclick=()=>modal('<h2>Extend a proven marketplace.</h2><ul class="checklist"><li>Eligible Instant Payouts for partner liquidity.</li><li>Billing for restaurant software tiers.</li><li>Reconciled payment data for marketplace analytics.</li></ul><p class="notice">LATER concepts. Country, account eligibility and business economics must be validated.</p>')}
 else if(page==='membership'){app.innerHTML=membershipPage();membershipBindings()}
 else if(page==='markets')app.innerHTML=marketsPage();
 else if(page==='value'){app.innerHTML=valuePage();valueBindings()}
 else app.innerHTML='<div class="empty">This page isn’t on the menu. <a href="#discover">Back to FoodNow</a></div>';
 localizeCheckoutLabels();
 if(page==='order'||['owner','ops','courier'].includes(page)&&!['menu','onboarding','stripe'].includes(sub)){poll=setInterval(()=>{if(!document.hidden&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,select'))route(true)},5000)}
 }catch(e){if(v!==version)return;if(quiet){toast(e.message);return}$('#app').innerHTML=`<div class="error">${escapeHtml(e.message)}</div><a class="button secondary" href="#${homes[portal]}">Back to workspace</a>`}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(b.dataset.restaurant)location.hash='restaurant/'+b.dataset.restaurant;if(b.dataset.add)add(b.dataset.add);if(b.dataset.qty){let item=cart.find(i=>i.dishId===b.dataset.qty);if(item){item.quantity=Math.min(10,item.quantity+Number(b.dataset.delta));cart=cart.filter(i=>i.quantity>0);saveCart();$('#cart-panel').innerHTML=bagMarkup()}}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x.dataset.category===category);x.setAttribute('aria-pressed',x.dataset.category===category)});filterRestaurants()}if(b.dataset.inspect)await inspectOrder(b.dataset.inspect);if(b.dataset.state){b.disabled=true;await setStatus(b.dataset.id,b.dataset.state);b.disabled=false}if(b.dataset.claim){b.disabled=true;await api('/api/orders/'+b.dataset.claim+'/assign',{});await route(true);toast('Delivery assigned to you')}if(b.dataset.review)reviewDialog(b.dataset.kind,b.dataset.id,b.dataset.review);if(b.dataset.editMenu)menuDialog(b.dataset.editMenu);if(b.dataset.partner)partnerDetails(b.dataset.partner,b.dataset.id);if(b.dataset.filterRestaurant)orderFilter=b.dataset.filterRestaurant}catch(err){b.disabled=false;toast(err.message)}});
$('#modal .close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});$('#guide-button').onclick=()=>modal('<h2>Follow one order across FoodNow</h2><ol class="checklist"><li>Diner: place an order as a guest or signed-in customer.</li><li>Restaurant: accept, prepare and mark it ready.</li><li>Courier: claim, pick up and confirm delivery.</li><li>Operations: inspect the journals and settle partner earnings.</li></ol><p class="notice">Open each workspace in a separate tab. Sign in using its own account; permissions are checked by the server.</p><a class="button" href="#portals">Open workspaces →</a>');
window.addEventListener('hashchange',()=>route());route();

function localizeCheckoutLabels(){
 if(activeLocale!=='fr-FR')return;
 const labels={'Delivery details':'Coordonnées de livraison','Name':'Nom','Email':'E-mail','Delivery address':'Adresse de livraison','Guest checkout':'Commande sans compte','Diner checkout':'Paiement client','Almost at your door.':'Bientôt à votre porte.','Food subtotal':'Sous-total des plats','Delivery':'Livraison','Service fee':'Frais de service','Total':'Total','Continue to payment':'Continuer vers le paiement','← Back to your bag':'← Retour au panier','Your bag is empty.':'Votre panier est vide.','Find a restaurant':'Trouver un restaurant'};
 const walk=document.createTreeWalker(document.querySelector('#app'),NodeFilter.SHOW_TEXT);let n;
 while(n=walk.nextNode()){const key=n.textContent.trim();if(labels[key])n.textContent=n.textContent.replace(key,labels[key]);}
}
